typedef enum {
    Z_IOERROR_TAG_NOTFOUND,
    Z_IOERROR_TAG_PERMISSIONDENIED,
    Z_IOERROR_TAG_INTERRUPTED,
    Z_IOERROR_TAG_INVALIDPATH,
    Z_IOERROR_TAG_EOF,
    Z_IOERROR_TAG_BADENCODING,
    Z_IOERROR_TAG_EXISTS,
    Z_IOERROR_TAG_ISDIR,
    Z_IOERROR_TAG_NOTDIR,
    Z_IOERROR_TAG_NOSPACE,
    Z_IOERROR_TAG_OTHER,
} z_t1557_tag_t;
struct z_t1557_t {
    uint8_t tag;
    void* data;
};
static void z_t1557_destroy(z_t1557_t* u) {
    if (!u) return;
    if (!u->data) return;
    switch (u->tag) {
        case Z_IOERROR_TAG_INVALIDPATH:
            z_t32_free((z_t32_t*)u->data);
            free(u->data);
            break;
        case Z_IOERROR_TAG_OTHER:
            z_t32_free((z_t32_t*)u->data);
            free(u->data);
            break;
        default: break;
    }
}

struct z_t1585_t {
    int32_t fd;
    bool closed;
};
static void z_t1585_destroy(z_t1585_t* p) {
    if (!p) return;
    if (p->closed) return;
    close(p->fd);
    p->closed = true;
}

